// src/App.js
import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom'; // Import React Router components
import './App.css'; // Your global App CSS
import Navbar from './components/Navbar';
import HeroSection from './components/HeroSection';
import About from './components/About';
import Projects from './components/Projects';
import Certifications from './components/Certifications';
import Contact from './components/Contact';

function App() {
  return (
    <Router basename="/aniket-awasthi-portfolio"> {/* IMPORTANT: Add your repo name as basename for GitHub Pages */}
      <div className="App">
        <Navbar /> {/* Navbar will always be visible */}
        <Routes>
          <Route path="/" element={<HeroSection />} />
          <Route path="/about" element={<About />} />
          <Route path="/projects" element={<Projects />} />
          <Route path="/certifications" element={<Certifications />} />
          <Route path="/contact" element={<Contact />} />
          {/* Optional: Add a catch-all route for 404 if desired */}
          {/* <Route path="*" element={<div><h1>404 Not Found</h1><p>The page you are looking for does not exist.</p></div>} /> */}
        </Routes>
      </div>
    </Router>
  );
}

export default App;