// src/components/HeroSection.js
import React from 'react';
import './HeroSection.css';
import { motion } from 'framer-motion';
import Typewriter from 'typewriter-effect';
import profilePic from '../assets/profile.jpg'; // Using 'profile.jpg' as seen in screenshot
import resume from '../assets/Aniket_FResume_7.pdf'; // Corrected: Using the exact resume filename 'Aniket_FResume_7.pdf'

const HeroSection = () => {
  const textVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.8 } }
  };

  const imageVariants = {
    hidden: { scale: 0 },
    visible: { scale: 1, transition: { duration: 0.8, ease: "easeOut" } }
  };

  const buttonVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.8, delay: 0.6 } }
  };

  return (
    <motion.section
      id="home"
      className="section hero-section"
      initial="hidden"
      animate="visible"
    >
      <div className="hero-content">
        <motion.img
          src={profilePic}
          alt="Aniket Awasthi"
          className="hero-image"
          variants={imageVariants}
        />
        <motion.h1 className="hero-title" variants={textVariants}>
          Hi, I am ANIKET AWASTHI.
        </motion.h1>
        <motion.p className="hero-subtitle" variants={textVariants}>
          <Typewriter
            options={{
              strings: ['Computer Science Engineer.', 'Innovate! Implement!! Impress!!!'],
              autoStart: true,
              loop: true,
              deleteSpeed: 50,
              delay: 75,
              wrapperClassName: 'typewriter-wrapper',
              cursorClassName: 'typewriter-cursor',
            }}
          />
        </motion.p>
        <motion.a
          href={resume}
          download="Aniket_Awasthi_Resume.pdf" // This is the filename the user will see when they download it.
          className="resume-button"
          variants={buttonVariants}
        >
          Download Resume
        </motion.a>
      </div>
    </motion.section>
  );
};

export default HeroSection;