// src/components/Projects.js
import React from 'react';
import { motion } from 'framer-motion';
import './Projects.css';

// Removed: import { Github, PlayCircle } from 'lucide-react'; // No longer needed as buttons are removed

const Projects = () => {
  const projectsData = [
    {
      id: 1,
      title: 'Movie Review Site',
      description: 'Developed a user-friendly interface with seamless navigation. Integrated trailer viewing functionality for better engagement. Implemented review and rating system using backend database.',
      technologies: ['HTML', 'CSS', 'JavaScript', 'MongoDB'],
      // Removed: githubLink and liveDemoLink properties
    },
    {
      id: 2,
      title: 'Pathshala – A Virtual Classroom',
      description: 'Designed and developed a virtual learning platform. Features include class scheduling, assignment submission, and study material sharing. Enhanced student-faculty interaction and digital learning experience.',
      technologies: ['HTML', 'CSS', 'JavaScript', 'MongoDB'],
      // Removed: githubLink and liveDemoLink properties
    },
    // Add more projects here following the same structure
  ];

  const sectionVariants = {
    hidden: { opacity: 0, y: 50 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.8,
        ease: "easeOut",
        staggerChildren: 0.2
      }
    }
  };

  const cardVariants = {
    hidden: { opacity: 0, scale: 0.9 },
    visible: { opacity: 1, scale: 1, transition: { duration: 0.5, ease: "easeOut" } }
  };

  return (
    <motion.section
      id="projects"
      className="section projects-section"
      initial="hidden"
      animate="visible"
      variants={sectionVariants}
    >
      <motion.h2 variants={sectionVariants}>My Projects</motion.h2>

      <div className="projects-grid">
        {projectsData.map(project => (
          <motion.div
            key={project.id}
            className="project-card"
            variants={cardVariants}
            whileHover={{ translateY: -8, boxShadow: "0 12px 25px rgba(0,0,0,0.6)" }}
            transition={{ type: "spring", stiffness: 300 }}
          >
            <h3>{project.title}</h3>
            <p className="project-description">{project.description}</p>
            <div className="technologies-list">
              {project.technologies.map((tech, index) => (
                <span key={index} className="tech-badge">{tech}</span>
              ))}
            </div>
            {/* Removed the project-links div entirely */}
          </motion.div>
        ))}
      </div>
    </motion.section>
  );
};

export default Projects;