import React from 'react';
import './Contact.css'; // Make sure this CSS file is present
import { Phone, Mail, Linkedin } from 'lucide-react'; // lucide-react seems to be what you're using based on icons

const Contact = () => {
  return (
    <section id="contact" className="contact-section">
      <h2>Contact Me</h2>
      <div className="contact-info"> {/* This div will wrap your contact items */}
        {/* Phone Contact */}
        <a href="tel:+918975875536" className="contact-item">
          <Phone size={28} /> {/* Increased icon size for better visibility */}
          <span>Phone: +91 8975875536</span>
        </a>

        {/* Email Contact */}
        <a href="mailto:awasthianiket007@gmail.com" className="contact-item">
          <Mail size={28} /> {/* Increased icon size */}
          <span>Email: awasthianiket007@gmail.com</span>
        </a>

        {/* LinkedIn Contact - CORRECTED HREF */}
        <a
          href="https://www.linkedin.com/in/aniketawasthi700?lipi=urn%3Ali%3Apage%3Ad_flagship3_profile_view_base_contact_details%3BMOyqngV6SKuEG8AyDzLl%2FA%3D%3D"
          target="_blank"
          rel="noopener noreferrer"
          className="contact-item"
        >
          <Linkedin size={28} /> {/* Increased icon size */}
          <span>LinkedIn: Aniket Awasthi</span>
        </a>
      </div>
      {/* Remove the social-links div if it's no longer used for icons; contact-item handles it */}
    </section>
  );
};

export default Contact;