// src/components/Navbar.js
import React, { useState } from 'react'; // Keep useState if you plan to implement a mobile/responsive toggle
import { Link } from 'react-router-dom'; // Import Link from react-router-dom
import './Navbar.css';

const Navbar = () => {
  // Assuming you might want a mobile toggle later, keeping useState for isOpen
  const [isOpen, setIsOpen] = useState(false);

  const toggleNavbar = () => {
    setIsOpen(!isOpen);
  };

  return (
    <nav className="navbar">
      <div className="navbar-brand">
        {/* Link to the Home/Hero section */}
        <Link to="/" className="navbar-logo">
          Aniket Awasthi {/* You can put your name or a logo here */}
        </Link>
      </div>
      {/* Optional: Mobile toggler button */}
      {/* <button className="navbar-toggler" onClick={toggleNavbar}>
        ☰
      </button> */}
      <div className={`navbar-links ${isOpen ? 'active' : ''}`}>
        <Link to="/about" className="navbar-item" onClick={toggleNavbar}>
          About
        </Link>
        <Link to="/projects" className="navbar-item" onClick={toggleNavbar}>
          Projects
        </Link>
        <Link to="/certifications" className="navbar-item" onClick={toggleNavbar}>
          Certifications
        </Link>
        <Link to="/contact" className="navbar-item" onClick={toggleNavbar}>
          Contact
        </Link>
      </div>
    </nav>
  );
};
export default Navbar;