// src/components/About.js
import React from 'react';
import { motion } from 'framer-motion';
import './About.css';
// import AboutBackground from '../assets/about-background.jpg'; // REMOVE THIS LINE - Background will be handled by CSS for consistency

const About = () => {
  const sectionVariants = {
    hidden: { opacity: 0, y: 50 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.8,
        ease: "easeOut",
        staggerChildren: 0.2
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, x: -50 },
    visible: { opacity: 1, x: 0 }
  };

  return (
    <motion.section
      id="about"
      className="section about-section"
      initial="hidden"
      animate="visible"
      variants={sectionVariants}
      // style={{ backgroundImage: `url(${AboutBackground})` }} // REMOVE THIS LINE
    >
      <div className="about-content">
        <motion.h2 variants={itemVariants}>About Me</motion.h2>
        <motion.ul variants={sectionVariants} className="about-list">
          <motion.li variants={itemVariants}>Pursued Bachelor of Engineering (B.E) specializing in <span className="highlight">Computer Science and Engineering</span> with a CGPA of <span className="highlight">8.12</span>.</motion.li>
          <motion.li variants={itemVariants}>Strong foundation in core programming languages:
            <ul>
              <li><span className="highlight">Java</span></li>
              <li><span className="highlight">HTML, CSS, JavaScript</span></li>
              <li><span className="highlight">MySQL</span></li>
              <li><span className="highlight">DSA</span></li>
            </ul>
          </motion.li>
          <motion.li variants={itemVariants}>Project Highlight: <span className="highlight">Pathshala – A Virtual Classroom</span>, built to enhance student-faculty academic interactions.</motion.li>
          <motion.li variants={itemVariants}>Web Development Intern at <span className="highlight">CodSoft</span>, where I worked on front-end development using Agile methodologies.</motion.li>
          <motion.li variants={itemVariants}>Actively engaged in continuous learning with multiple certifications and coding competition participation.</motion.li>
          <motion.li variants={itemVariants}>Eager to join a dynamic team to apply my knowledge, grow collaboratively, and contribute to innovative software projects.</motion.li>
        </motion.ul>
      </div>
    </motion.section>
  );
};

export default About;